import re, pathlib, collections
pat = re.compile(r"pytest\.skip\(|self\.skipTest\(|pytest\.mark\.skipif|unittest\.skipIf|unittest\.skipUnless|skipIf\(")
tot = 0; byfile = collections.Counter()
for p in pathlib.Path('tests').rglob('*.py'):
    if '__pycache__' in str(p): continue
    for line in p.read_text(errors='replace').splitlines():
        if pat.search(line):
            tot += 1; byfile[str(p)] += 1
print('TOTAL skip sites:', tot, 'in', len(byfile), 'files')
for f, c in byfile.most_common(6): print(c, f)
